<?php session_start(); require_once __DIR__.'/../config/database.php'; require_role('student'); $data=db_load(); $id=(int)($_GET['id']??0); $internship=db_internship($data,$id); $message=''; $messageType='success'; $student=db_student_by_user($data,(int)$_SESSION['user_id']); $sid=(int)($student['id']??0); $already=false; if($internship && $internship['status']==='Open'){ foreach($data['applications'] as $a) if((int)$a['student_id']===$sid && (int)$a['internship_id']===$id) $already=true; if($_SERVER['REQUEST_METHOD']==='POST' && !$already){ $data['applications'][]=['id'=>db_next_id($data,'applications'),'student_id'=>$sid,'internship_id'=>$id,'status'=>'Applied','applied_at'=>db_now()]; if(db_save($data)){$message='Application submitted successfully.';}else{$message='Could not save your application.';$messageType='error';} } elseif($already){$message='You already applied for this internship.';$messageType='error';} } $company=$internship?db_company($data,(int)$internship['company_id']):null; ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Apply · Arti Vaniyar Internships Hub</title><link rel="stylesheet" href="../css/style.css"></head><body><?php include 'student_nav.php'; ?><main class="dashboard narrow"><?php if(!$internship || !$company): ?><div class="alert error">Internship not found.</div><?php else: ?><div class="detail-card"><span class="status open">Open</span><h1><?=e($internship['title'])?></h1><h3><?=e($company['company_name'])?></h3><p><?=nl2br(e($internship['description']))?></p><div class="detail-info"><p><strong>Location:</strong> <?=e($internship['location'])?></p><p><strong>Skills:</strong> <?=e($internship['skills']?:'Not specified')?></p><p><strong>Duration:</strong> <?=e($internship['duration']?:'Not specified')?></p><p><strong>Stipend:</strong> <?=e($internship['stipend']?:'Not specified')?></p></div><?php if($message): ?><div class="alert <?=$messageType==='success'?'success':'error'?>"><?=e($message)?></div><?php endif; ?><?php if(!$already && $message===''): ?><form method="POST"><button class="btn primary" type="submit">Apply now</button></form><?php endif; ?></div><?php endif; ?></main></body></html>
